    var rate = rates.settlementRate(t.currency(), businessDate);
    boolean fromSettlementSource = rates.quote(t.currency(), businessDate).lagged();
    long krw = Money.toKrw(t.signedAmount(), rate, CurrencyPairs.unitOf(t.currency()));
    return new SettledTxn(t.id(), t.partnerId(), businessDate, t.currency(), t.signedAmount(), rate,
            fromSettlementSource, krw);
}

