/**
 * Per-transaction text for a partner. Lines on lagged-quote days carry the vendor's source-3 rate,
 * which is B-2 contract data and must not leave the company, so that rate is shown as "-"
 * (see docs/notes/2025-11-18-vendor-review.md). The KRW amount is still the settled amount.
 */
public static String partnerDetail(Partner p, LocalDate from, LocalDate to, List<SettledTxn> txns) {
    StringBuilder sb = new StringBuilder();
    sb.append(String.format("%s %s  %s ~ %s%n", p.id(), p.name(), from, to));
    long gross = 0;
    for (SettledTxn t : txns) {
        String rate = t.fromSettlementSource() ? "-" : Money.rate(t.rate()) + ("JPY".equals(t.currency()) ? "/100엔" : "");
        sb.append(String.format("%s  %s  %s %12s  %12s  %12s%n",
                t.txnId(), t.date(), t.currency(), foreign(t.amount(), t.currency()), rate, Money.won(t.krw())));
        gross += t.krw();
    }
    sb.append(String.format("합계 %d건 %s%n", txns.size(), Money.won(gross)));
    return sb.toString();
}

private static String foreign(BigDecimal amount, String currency) {
    String pattern = "JPY".equals(currency) ? "#,##0" : "#,##0.00";
    return new DecimalFormat(pattern, DecimalFormatSymbols.getInstance(Locale.ROOT)).format(amount);
}

